head.b:skin:
/* ==========================================================================
   Islamic Geometric Patterns & Ornamental Styles
   راہِ دینِ اسلام (Rah-e-Deen-Islam)
   ========================================================================== */

:root {
  --islamic-star-pattern: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23d4af37' fill-opacity='0.08'%3E%3Cpath d='M30 0l7.5 17.5L55 10l-7.5 20L60 37.5 42.5 45 50 60l-20-7.5L22.5 60 15 42.5 0 50l7.5-20L0 22.5 17.5 15 10 0l20 7.5z'/%3E%3Ccircle cx='30' cy='30' r='5'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
  --islamic-lattice-pattern: url("data:image/svg+xml,%3Csvg width='40' height='40' viewBox='0 0 40 40' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M20 0 L40 20 L20 40 L0 20 Z' fill='none' stroke='%23d4af37' stroke-width='0.75' stroke-opacity='0.12'/%3E%3Cpath d='M20 5 L35 20 L20 35 L5 20 Z' fill='none' stroke='%23d4af37' stroke-width='0.5' stroke-opacity='0.08'/%3E%3Ccircle cx='20' cy='20' r='2' fill='%23d4af37' fill-opacity='0.15'/%3E%3C/svg%3E");
  --islamic-border-arch: url("data:image/svg+xml,%3Csvg width='100' height='20' viewBox='0 0 100 20' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0,20 Q25,0 50,20 Q75,0 100,20' fill='none' stroke='%23d4af37' stroke-width='1' stroke-opacity='0.3'/%3E%3C/svg%3E");
}

/* Background Pattern Classes */
.bg-islamic-stars {
  background-image: var(--islamic-star-pattern);
}

.bg-islamic-lattice {
  background-image: var(--islamic-lattice-pattern);
}

/* Mihrab Arch Header Ornament */
.mihrab-arch {
  position: relative;
  border-top-left-radius: 40px;
  border-top-right-radius: 40px;
}

.mihrab-arch::before {
  content: '';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  width: 140px;
  height: 24px;
  background: radial-gradient(ellipse at center, rgba(212, 175, 55, 0.4) 0%, rgba(212, 175, 55, 0) 70%);
  pointer-events: none;
}

/* Golden Ornamental Dividers */
.gold-divider {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin: 28px 0;
}

.gold-divider::before,
.gold-divider::after {
  content: '';
  height: 1.5px;
  flex: 1;
  max-width: 160px;
  background: linear-gradient(90deg, transparent, rgba(212, 175, 55, 0.6), transparent);
}

.gold-divider-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  color: var(--gold-500);
  transform: rotate(45deg);
  border: 1px solid rgba(212, 175, 55, 0.5);
  background: rgba(6, 78, 59, 0.4);
}

.gold-divider-icon span {
  transform: rotate(-45deg);
  font-size: 14px;
  line-height: 1;
}

/* Crescent and Lantern Badges */
.crescent-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  background: rgba(212, 175, 55, 0.12);
  border: 1px solid rgba(212, 175, 55, 0.35);
  border-radius: 20px;
  color: var(--gold-400);
  font-size: 0.85rem;
  font-weight: 600;
}

/* Islamic Card Crest */
.card-crest {
  position: relative;
  overflow: hidden;
}

.card-crest::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, transparent, var(--gold-500), transparent);
}


/* ==========================================================================
   راہِ دینِ اسلام (Rah-e-Deen-Islam) — Master Stylesheet
   Crafted for authentic Islamic education in Pakistan
   Colors: Emerald Green (#064E3B, #022C22), Gold (#D4AF37), Ivory (#FCFBF7)
   Typography: Noto Nastaliq Urdu, Amiri Arabic, Plus Jakarta Sans
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Amiri:ital,wght@0,400;0,700;1,400&family=Noto+Nastaliq+Urdu:wght@400;600;700&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap');

:root {
  /* Core Color Palette */
  --emerald-950: #011c15;
  --emerald-900: #022c22;
  --emerald-850: #04392c;
  --emerald-800: #064e3b;
  --emerald-700: #047857;
  --emerald-600: #059669;
  --emerald-100: #d1fae5;
  --emerald-50:  #ecfdf5;

  --gold-600: #aa771c;
  --gold-500: #d4af37;
  --gold-400: #e5c158;
  --gold-300: #f3d889;
  --gold-100: #fef7db;
  --gold-50:  #fdfcf7;

  --ivory-50:  #ffffff;
  --ivory-100: #fcfbf7;
  --ivory-200: #f7f4ec;
  --ivory-300: #efe9dc;
  --text-dark: #1a2421;
  --text-muted: #4b5e56;

  /* Typography Stacks */
  --font-urdu: 'Noto Nastaliq Urdu', 'Jameel Noori Nastaliq', 'Alvi Nastaleeq', 'Urdu Typesetting', serif;
  --font-arabic: 'Amiri', 'Traditional Arabic', 'Scheherazade New', serif;
  --font-ui: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;

  /* UI Tokens */
  --border-radius-sm: 8px;
  --border-radius-md: 14px;
  --border-radius-lg: 20px;
  --border-radius-xl: 32px;
  --shadow-sm: 0 2px 6px rgba(2, 44, 34, 0.05);
  --shadow-md: 0 6px 18px rgba(2, 44, 34, 0.08);
  --shadow-lg: 0 14px 34px rgba(2, 44, 34, 0.12);
  --shadow-gold: 0 4px 20px rgba(212, 175, 55, 0.25);
  --transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Base Reset & RTL */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  direction: rtl;
}

body {
  font-family: var(--font-urdu);
  font-size: 1.05rem;
  line-height: 2.1;
  color: var(--text-dark);
  background-color: var(--ivory-100);
  background-image: radial-gradient(circle at 10% 20%, rgba(212, 175, 55, 0.04) 0%, transparent 40%),
                    radial-gradient(circle at 90% 80%, rgba(6, 78, 59, 0.03) 0%, transparent 40%);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* Accessibility & Focus */
:focus-visible {
  outline: 3px solid var(--gold-400);
  outline-offset: 3px;
}

.skip-link {
  position: absolute;
  top: -60px;
  right: 16px;
  background: var(--gold-500);
  color: var(--emerald-950);
  padding: 8px 16px;
  border-radius: var(--border-radius-sm);
  font-weight: 700;
  z-index: 9999;
  transition: top 0.2s ease;
  text-decoration: none;
}
.skip-link:focus {
  top: 16px;
}

/* Arabic & Quranic Styles */
.arabic-text {
  font-family: var(--font-arabic);
  font-size: 1.55rem;
  line-height: 2.2;
  color: var(--emerald-900);
  direction: rtl;
  text-align: right;
  letter-spacing: 0.5px;
}

.urdu-text {
  font-family: var(--font-urdu);
  line-height: 2.2;
}

/* Header & Top Bar */
.top-bar {
  background: var(--emerald-950);
  color: var(--ivory-200);
  padding: 8px 24px;
  border-bottom: 1px solid rgba(212, 175, 55, 0.3);
  font-size: 0.88rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.top-bar-info {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.top-bar-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.top-bar-item .icon {
  color: var(--gold-400);
}

.lang-selector {
  display: flex;
  align-items: center;
  gap: 6px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(212, 175, 55, 0.4);
  border-radius: 20px;
  padding: 2px 8px;
}

.lang-btn {
  background: none;
  border: none;
  color: var(--ivory-200);
  padding: 2px 10px;
  font-size: 0.85rem;
  font-family: var(--font-arabic);
  cursor: pointer;
  border-radius: 12px;
  transition: var(--transition);
}

.lang-btn.active, .lang-btn:hover {
  background: var(--gold-500);
  color: var(--emerald-950);
  font-weight: 700;
}

/* Main Site Header */
.site-header {
  background: linear-gradient(135deg, var(--emerald-900) 0%, var(--emerald-800) 100%);
  color: #fff;
  border-bottom: 3px solid var(--gold-500);
  box-shadow: var(--shadow-md);
  position: sticky;
  top: 0;
  z-index: 1000;
}

.header-container {
  max-width: 1300px;
  margin: 0 auto;
  padding: 14px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

.brand-wrapper {
  display: flex;
  align-items: center;
  gap: 14px;
  text-decoration: none;
  color: inherit;
}

.brand-logo-img {
  width: 58px;
  height: 58px;
  flex-shrink: 0;
  filter: drop-shadow(0 2px 6px rgba(0,0,0,0.3));
}

.brand-text h1 {
  font-family: var(--font-urdu);
  font-size: 1.85rem;
  font-weight: 700;
  color: var(--gold-400);
  margin-bottom: -4px;
  line-height: 1.3;
}

.brand-text p {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  letter-spacing: 2px;
  color: var(--ivory-200);
  text-transform: uppercase;
}

/* Navigation Menu */
.nav-toggle-btn {
  display: none;
  background: rgba(212, 175, 55, 0.15);
  border: 1px solid var(--gold-500);
  color: var(--gold-400);
  padding: 8px 12px;
  border-radius: var(--border-radius-sm);
  cursor: pointer;
  font-size: 1.25rem;
}

.main-navigation {
  display: flex;
  align-items: center;
}

.nav-list {
  display: flex;
  align-items: center;
  list-style: none;
  gap: 6px;
  flex-wrap: wrap;
}

.nav-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: 20px;
  color: var(--ivory-100);
  text-decoration: none;
  font-size: 0.96rem;
  font-weight: 500;
  transition: var(--transition);
  border: 1px solid transparent;
  cursor: pointer;
  background: transparent;
}

.nav-link:hover, .nav-link.active {
  background: rgba(212, 175, 55, 0.18);
  color: var(--gold-300);
  border-color: rgba(212, 175, 55, 0.4);
}

.nav-link.active {
  background: var(--gold-500);
  color: var(--emerald-950);
  font-weight: 700;
}

/* Hero Section */
.hero-section {
  position: relative;
  background: linear-gradient(180deg, var(--emerald-900) 0%, var(--emerald-850) 60%, var(--emerald-800) 100%);
  color: #fff;
  padding: 48px 24px 64px;
  text-align: center;
  overflow: hidden;
  border-bottom: 1px solid rgba(212, 175, 55, 0.3);
}

.hero-content {
  position: relative;
  max-width: 900px;
  margin: 0 auto;
  z-index: 2;
}

.bismillah-calligraphy {
  font-family: var(--font-arabic);
  font-size: 2.2rem;
  color: var(--gold-400);
  margin-bottom: 16px;
  text-shadow: 0 2px 10px rgba(0,0,0,0.3);
}

.hero-title {
  font-family: var(--font-urdu);
  font-size: 2.8rem;
  font-weight: 700;
  color: #ffffff;
  margin-bottom: 12px;
  line-height: 1.5;
}

.hero-title span {
  color: var(--gold-400);
}

.hero-subtitle {
  font-family: var(--font-urdu);
  font-size: 1.25rem;
  color: var(--ivory-200);
  margin-bottom: 28px;
  max-width: 750px;
  margin-left: auto;
  margin-right: auto;
  line-height: 2.1;
}

.hero-actions {
  display: flex;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  margin-top: 24px;
}

/* Button Component */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 24px;
  border-radius: var(--border-radius-md);
  font-family: var(--font-urdu);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  text-decoration: none;
  transition: var(--transition);
  border: 1px solid transparent;
}

.btn-gold {
  background: linear-gradient(135deg, var(--gold-400) 0%, var(--gold-500) 100%);
  color: var(--emerald-950);
  box-shadow: 0 4px 14px rgba(212, 175, 55, 0.35);
  border-color: var(--gold-300);
}

.btn-gold:hover {
  background: linear-gradient(135deg, var(--gold-300) 0%, var(--gold-400) 100%);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(212, 175, 55, 0.45);
}

.btn-emerald {
  background: var(--emerald-700);
  color: #ffffff;
  border-color: var(--emerald-600);
}

.btn-emerald:hover {
  background: var(--emerald-600);
  transform: translateY(-2px);
}

.btn-outline-gold {
  background: rgba(212, 175, 55, 0.08);
  border: 1.5px solid var(--gold-400);
  color: var(--gold-300);
}

.btn-outline-gold:hover {
  background: var(--gold-500);
  color: var(--emerald-950);
  transform: translateY(-2px);
}

.btn-sm {
  padding: 6px 14px;
  font-size: 0.88rem;
  border-radius: var(--border-radius-sm);
}

/* Prayer Times Banner Widget */
.prayer-quick-bar {
  background: var(--ivory-50);
  border-bottom: 1px solid var(--ivory-300);
  box-shadow: var(--shadow-sm);
  padding: 16px 24px;
}

.prayer-bar-container {
  max-width: 1300px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}

.prayer-city-select-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
}

.city-select {
  font-family: var(--font-urdu);
  padding: 6px 16px;
  border-radius: var(--border-radius-sm);
  border: 1.5px solid var(--gold-500);
  background-color: #fff;
  color: var(--emerald-900);
  font-weight: 600;
  cursor: pointer;
  outline: none;
}

.prayer-chips {
  display: flex;
  align-items: center;
  gap: 10px;
  overflow-x: auto;
  padding: 6px 2px;
  scrollbar-width: thin;
  scrollbar-color: var(--gold-400) transparent;
}

.prayer-chips::-webkit-scrollbar {
  height: 5px;
}

.prayer-chips::-webkit-scrollbar-thumb {
  background: var(--gold-400);
  border-radius: 4px;
}

.prayer-chip {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 6px 12px;
  background: var(--ivory-200);
  border-radius: var(--border-radius-sm);
  border: 1px solid rgba(212, 175, 55, 0.3);
  min-width: 86px;
  white-space: nowrap;
  transition: var(--transition);
  flex-shrink: 0;
}

.prayer-chip.active {
  background: var(--emerald-800);
  color: #fff;
  border-color: var(--gold-400);
  box-shadow: 0 4px 12px rgba(6, 78, 59, 0.25);
}

.prayer-chip .p-type-tag {
  font-size: 0.65rem;
  padding: 1px 6px;
  border-radius: 6px;
  margin-bottom: 2px;
  font-weight: 700;
  line-height: 1.2;
}

.prayer-chip .p-tag-fard {
  background: rgba(6, 78, 59, 0.12);
  color: var(--emerald-900);
}

.prayer-chip .p-tag-nafl {
  background: rgba(212, 175, 55, 0.25);
  color: #854d0e;
}

.prayer-chip .p-tag-sun {
  background: rgba(245, 158, 11, 0.2);
  color: #92400e;
}

.prayer-chip.active .p-tag-fard,
.prayer-chip.active .p-tag-nafl,
.prayer-chip.active .p-tag-sun {
  background: rgba(255, 255, 255, 0.25);
  color: #ffffff;
}

.prayer-chip .p-name {
  font-size: 0.82rem;
  font-weight: 600;
}

.prayer-chip .p-time {
  font-family: var(--font-ui);
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--emerald-950);
}

.prayer-chip.active .p-time {
  color: var(--gold-300);
}

.prayer-countdown-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--gold-100);
  border: 1px solid var(--gold-500);
  padding: 6px 14px;
  border-radius: 20px;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--emerald-950);
}

/* Full Prayer Dashboard Cards */
.prayer-card-full {
  transition: var(--transition);
}

.prayer-card-full:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.active-prayer-card {
  border-color: var(--gold-500) !important;
  box-shadow: 0 8px 24px rgba(212, 175, 55, 0.25) !important;
  background: linear-gradient(180deg, #fefce8 0%, #ffffff 100%) !important;
  transform: translateY(-3px);
}

/* Main Layout & App Container */
.main-content {
  flex: 1;
  max-width: 1300px;
  width: 100%;
  margin: 0 auto;
  padding: 36px 20px 60px;
}

/* Page / View Container */
.page-view {
  display: none;
  animation: fadeIn 0.3s ease-in-out;
}

.page-view.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Section Header */
.section-header {
  text-align: center;
  margin-bottom: 36px;
  position: relative;
}

.section-badge {
  display: inline-block;
  background: rgba(212, 175, 55, 0.15);
  border: 1px solid var(--gold-500);
  color: var(--gold-600);
  padding: 4px 16px;
  border-radius: 20px;
  font-size: 0.9rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.section-title {
  font-size: 2.1rem;
  color: var(--emerald-900);
  font-weight: 700;
  margin-bottom: 8px;
}

.section-desc {
  color: var(--text-muted);
  max-width: 750px;
  margin: 0 auto;
  font-size: 1.05rem;
}

/* Cards & Layout Grids */
.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 24px;
  margin-top: 24px;
}

.card {
  background: var(--ivory-50);
  border: 1px solid var(--ivory-300);
  border-radius: var(--border-radius-md);
  box-shadow: var(--shadow-sm);
  padding: 24px;
  transition: var(--transition);
  position: relative;
  display: flex;
  flex-direction: column;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: rgba(212, 175, 55, 0.5);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--ivory-200);
  padding-bottom: 12px;
  margin-bottom: 16px;
}

.card-title {
  font-size: 1.25rem;
  color: var(--emerald-900);
  font-weight: 700;
}

/* Hadith Cards Specific */
.hadith-card {
  background: #ffffff;
  border: 1.5px solid rgba(212, 175, 55, 0.35);
  border-radius: var(--border-radius-md);
  padding: 24px;
  margin-bottom: 24px;
  box-shadow: var(--shadow-sm);
  position: relative;
  transition: var(--transition);
}

.hadith-card:hover {
  border-color: var(--gold-500);
  box-shadow: var(--shadow-md);
}

.hadith-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  padding-bottom: 12px;
  margin-bottom: 16px;
  border-bottom: 1px dashed rgba(212, 175, 55, 0.4);
}

.hadith-number-badge {
  background: var(--emerald-800);
  color: var(--gold-300);
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 0.88rem;
  font-weight: 700;
}

.hadith-grade-badge {
  background: var(--emerald-50);
  color: var(--emerald-700);
  border: 1px solid var(--emerald-600);
  padding: 2px 10px;
  border-radius: 12px;
  font-size: 0.82rem;
  font-weight: 600;
}

.hadith-arabic {
  background: var(--ivory-100);
  border-right: 4px solid var(--gold-500);
  padding: 18px 20px;
  border-radius: var(--border-radius-sm);
  margin-bottom: 16px;
}

.hadith-urdu {
  color: var(--text-dark);
  font-size: 1.1rem;
  line-height: 2.2;
  margin-bottom: 18px;
}

.hadith-section-box {
  background: var(--emerald-50);
  border: 1px solid var(--emerald-100);
  border-radius: var(--border-radius-sm);
  padding: 14px 18px;
  margin-top: 12px;
}

.hadith-section-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--emerald-900);
  margin-bottom: 4px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.hadith-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 20px;
  padding-top: 12px;
  border-top: 1px solid var(--ivory-200);
}

/* Search & Filters */
.search-filter-bar {
  background: var(--ivory-50);
  border: 1.5px solid var(--gold-400);
  border-radius: var(--border-radius-md);
  padding: 18px 20px;
  margin-bottom: 28px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.search-input-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.search-input {
  width: 100%;
  padding: 12px 48px 12px 18px;
  font-family: var(--font-urdu);
  font-size: 1.05rem;
  border: 1px solid var(--ivory-300);
  border-radius: var(--border-radius-sm);
  outline: none;
  transition: var(--transition);
}

.search-input:focus {
  border-color: var(--gold-500);
  box-shadow: 0 0 0 3px rgba(212, 175, 55, 0.2);
}

.search-icon {
  position: absolute;
  right: 16px;
  color: var(--gold-600);
  font-size: 1.2rem;
}

.filter-chips {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.filter-chip {
  background: var(--ivory-200);
  border: 1px solid var(--ivory-300);
  padding: 4px 14px;
  border-radius: 20px;
  font-size: 0.9rem;
  cursor: pointer;
  transition: var(--transition);
  font-family: var(--font-urdu);
}

.filter-chip:hover, .filter-chip.active {
  background: var(--emerald-800);
  color: #fff;
  border-color: var(--emerald-900);
}

/* Tabs & Parts Switcher */
.parts-switcher {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.part-btn {
  padding: 10px 24px;
  border-radius: var(--border-radius-md);
  font-family: var(--font-urdu);
  font-size: 1.05rem;
  font-weight: 700;
  cursor: pointer;
  border: 1.5px solid var(--gold-500);
  background: #ffffff;
  color: var(--emerald-900);
  transition: var(--transition);
}

.part-btn:hover, .part-btn.active {
  background: var(--emerald-800);
  color: var(--gold-300);
  border-color: var(--gold-400);
  box-shadow: var(--shadow-gold);
}

/* Pagination Controls */
.pagination-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-top: 32px;
  flex-wrap: wrap;
}

.page-btn {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--border-radius-sm);
  border: 1px solid var(--ivory-300);
  background: #ffffff;
  color: var(--text-dark);
  font-family: var(--font-ui);
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
}

.page-btn:hover, .page-btn.active {
  background: var(--emerald-800);
  color: var(--gold-400);
  border-color: var(--gold-500);
}

/* Q&A Accordion Item */
.qa-card {
  background: #ffffff;
  border: 1px solid var(--ivory-300);
  border-radius: var(--border-radius-md);
  margin-bottom: 20px;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.qa-card:hover {
  border-color: var(--gold-500);
}

.qa-header {
  padding: 20px 24px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background: var(--ivory-50);
  user-select: none;
}

.qa-header h3 {
  font-size: 1.2rem;
  color: var(--emerald-900);
  font-weight: 700;
}

.qa-toggle-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 1px solid var(--gold-500);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gold-600);
  font-weight: 700;
  transition: transform 0.3s ease;
  flex-shrink: 0;
}

.qa-card.open .qa-toggle-icon {
  transform: rotate(180deg);
  background: var(--emerald-800);
  color: var(--gold-400);
}

.qa-body {
  padding: 0 24px 24px;
  display: none;
  border-top: 1px dashed var(--ivory-300);
  background: #ffffff;
}

.qa-card.open .qa-body {
  display: block;
}

.qa-block {
  margin-top: 18px;
  padding: 14px 18px;
  border-radius: var(--border-radius-sm);
}

.qa-block-short {
  background: var(--gold-50);
  border-right: 4px solid var(--gold-500);
}

.qa-block-evidence {
  background: var(--emerald-50);
  border-right: 4px solid var(--emerald-700);
}

.qa-block-scholars {
  background: #f8fafc;
  border-right: 4px solid #64748b;
}

.qa-block-rajih {
  background: #f0fdf4;
  border: 1.5px solid var(--emerald-600);
}

/* Fiqh Differences Comparison Grid */
.fiqh-differences-card {
  background: #ffffff;
  border: 2px solid var(--gold-400);
  border-radius: var(--border-radius-md);
  padding: 24px;
  margin-bottom: 28px;
  box-shadow: var(--shadow-md);
}

.fiqh-schools-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 16px;
  margin: 20px 0;
}

.fiqh-school-box {
  background: var(--ivory-100);
  border: 1px solid var(--ivory-300);
  border-radius: var(--border-radius-sm);
  padding: 16px;
}

.fiqh-school-title {
  font-weight: 700;
  color: var(--emerald-900);
  border-bottom: 1px solid var(--gold-400);
  padding-bottom: 6px;
  margin-bottom: 10px;
  display: flex;
  justify-content: space-between;
}

.fiqh-conclusion-box {
  background: linear-gradient(135deg, var(--emerald-900) 0%, var(--emerald-850) 100%);
  color: #ffffff;
  padding: 20px;
  border-radius: var(--border-radius-md);
  border: 1.5px solid var(--gold-400);
  margin-top: 20px;
}

.fiqh-conclusion-title {
  color: var(--gold-400);
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 8px;
}

/* Wudu Step-by-Step Flow */
.wudu-step-card {
  display: flex;
  gap: 20px;
  background: #ffffff;
  border: 1.5px solid var(--ivory-300);
  border-radius: var(--border-radius-md);
  padding: 20px;
  margin-bottom: 20px;
  box-shadow: var(--shadow-sm);
  align-items: flex-start;
}

.wudu-step-badge {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background: var(--emerald-800);
  color: var(--gold-400);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-ui);
  font-size: 1.35rem;
  font-weight: 700;
  flex-shrink: 0;
  border: 2px solid var(--gold-400);
}

.wudu-step-content {
  flex: 1;
}

.wudu-step-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
}

.wudu-type-tag {
  font-size: 0.82rem;
  padding: 2px 10px;
  border-radius: 12px;
  font-weight: 700;
}

.wudu-type-fard {
  background: #fee2e2;
  color: #991b1b;
  border: 1px solid #f87171;
}

.wudu-type-sunnah {
  background: var(--emerald-50);
  color: var(--emerald-800);
  border: 1px solid var(--emerald-600);
}

/* Wudu Checklist & Print view */
.wudu-checklist-box {
  background: var(--ivory-50);
  border: 1.5px solid var(--gold-500);
  border-radius: var(--border-radius-md);
  padding: 24px;
  margin-top: 32px;
}

.checklist-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px solid var(--ivory-200);
  cursor: pointer;
}

.checklist-checkbox {
  width: 20px;
  height: 20px;
  accent-color: var(--emerald-700);
  cursor: pointer;
}

/* Months & Events Grid */
.calendar-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(290px, 1fr));
  gap: 20px;
}

.month-card {
  background: #ffffff;
  border: 1px solid var(--ivory-300);
  border-radius: var(--border-radius-md);
  padding: 20px;
  transition: var(--transition);
  position: relative;
}

.month-card.sacred {
  border: 1.5px solid var(--gold-400);
  background: var(--gold-50);
}

.month-badge {
  position: absolute;
  top: 14px;
  left: 14px;
  font-size: 0.8rem;
  padding: 2px 8px;
  border-radius: 10px;
}

.month-sacred-badge {
  background: var(--gold-500);
  color: var(--emerald-950);
  font-weight: 700;
}

/* Surah Cards */
.surah-card {
  background: #ffffff;
  border: 1px solid var(--ivory-300);
  border-radius: var(--border-radius-md);
  padding: 22px;
  margin-bottom: 20px;
  transition: var(--transition);
}

.surah-card:hover {
  border-color: var(--gold-500);
  box-shadow: var(--shadow-md);
}

.surah-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
}

.surah-number {
  font-family: var(--font-ui);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--emerald-800);
  color: var(--gold-300);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
}

/* Contact & Forms */
.form-group {
  margin-bottom: 18px;
}

.form-label {
  display: block;
  font-weight: 600;
  margin-bottom: 6px;
  color: var(--emerald-900);
}

.form-control {
  width: 100%;
  padding: 10px 14px;
  font-family: var(--font-urdu);
  font-size: 1rem;
  border: 1.5px solid var(--ivory-300);
  border-radius: var(--border-radius-sm);
  outline: none;
  transition: var(--transition);
}

.form-control:focus {
  border-color: var(--gold-500);
  box-shadow: 0 0 0 3px rgba(212, 175, 55, 0.2);
}

textarea.form-control {
  min-height: 120px;
  resize: vertical;
}

/* Modals */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(2, 44, 34, 0.7);
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: 20px;
}

.modal-overlay.open {
  display: flex;
}

.modal-card {
  background: #ffffff;
  border-radius: var(--border-radius-lg);
  max-width: 650px;
  width: 100%;
  max-height: 90vh;
  overflow-y: auto;
  box-shadow: var(--shadow-lg);
  border: 2px solid var(--gold-500);
  padding: 28px;
  position: relative;
}

.modal-close-btn {
  position: absolute;
  top: 20px;
  left: 20px;
  background: none;
  border: none;
  font-size: 1.4rem;
  color: var(--text-muted);
  cursor: pointer;
  line-height: 1;
}

/* Toast Notifications */
.toast-container {
  position: fixed;
  bottom: 24px;
  left: 24px;
  z-index: 10000;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.toast {
  background: var(--emerald-900);
  color: #fff;
  border-right: 4px solid var(--gold-500);
  padding: 12px 20px;
  border-radius: var(--border-radius-sm);
  box-shadow: var(--shadow-lg);
  font-size: 0.95rem;
  display: flex;
  align-items: center;
  gap: 10px;
  animation: slideIn 0.3s ease-out;
}

@keyframes slideIn {
  from { transform: translateX(-100%); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

/* Site Footer */
.site-footer {
  background: var(--emerald-950);
  color: var(--ivory-200);
  border-top: 3px solid var(--gold-500);
  padding: 48px 24px 24px;
  margin-top: auto;
}

.footer-container {
  max-width: 1300px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 36px;
  padding-bottom: 32px;
  border-bottom: 1px solid rgba(212, 175, 55, 0.25);
}

.footer-col h4 {
  color: var(--gold-400);
  font-size: 1.25rem;
  margin-bottom: 16px;
  font-weight: 700;
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-links a {
  color: var(--ivory-200);
  text-decoration: none;
  transition: var(--transition);
}

.footer-links a:hover {
  color: var(--gold-400);
  padding-right: 6px;
}

.footer-bottom {
  max-width: 1300px;
  margin: 24px auto 0;
  text-align: center;
  font-size: 0.9rem;
  color: rgba(255, 255, 255, 0.6);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

/* Print Styles */
@media print {
  body {
    background: #ffffff !important;
    color: #000000 !important;
  }
  .site-header, .top-bar, .hero-section, .search-filter-bar,
  .parts-switcher, .pagination-wrap, .site-footer, .nav-toggle-btn,
  .btn, .toast-container, .modal-overlay {
    display: none !important;
  }
  .page-view {
    display: block !important;
  }
  .card, .hadith-card, .wudu-step-card, .qa-card {
    border: 1px solid #ccc !important;
    page-break-inside: avoid;
    box-shadow: none !important;
  }
}

/* Media Queries & Responsive */
@media (max-width: 992px) {
  .nav-toggle-btn {
    display: block;
  }
  .main-navigation {
    position: fixed;
    top: 76px;
    right: 0;
    left: 0;
    bottom: 0;
    background: var(--emerald-950);
    padding: 24px;
    display: none;
    flex-direction: column;
    align-items: stretch;
    overflow-y: auto;
    z-index: 999;
  }
  .main-navigation.mobile-open {
    display: flex;
  }
  .nav-list {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }
  .nav-link {
    padding: 12px 18px;
    font-size: 1.1rem;
    border-radius: var(--border-radius-sm);
  }
}

@media (max-width: 600px) {
  .hero-title {
    font-size: 2.1rem;
  }
  .hero-subtitle {
    font-size: 1.05rem;
  }
  .cards-grid {
    grid-template-columns: 1fr;
  }
  .wudu-step-card {
    flex-direction: column;
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}


/* Blogger Integration Adaptations */
.blogger-posts-wrapper {
  margin: 28px 0;
}
.blogger-posts-wrapper .post {
  margin-bottom: 24px;
}
.blogger-posts-wrapper .post-title {
  font-size: 1.45rem;
  color: var(--emerald-900);
  margin-bottom: 8px;
}
.blogger-posts-wrapper .post-title a {
  color: inherit;
  text-decoration: none;
}
.blogger-posts-wrapper .post-title a:hover {
  color: var(--gold-600);
}
.blogger-posts-wrapper .post-meta {
  font-size: 0.85rem;
  color: var(--text-muted);
  border-bottom: 1px dashed rgba(212, 175, 55, 0.4);
  padding-bottom: 6px;
  margin-bottom: 14px;
}

body.script:
  //

/* ===== START FILE: prayer-times.js ===== */
/**
 * Comprehensive Automatic Prayer & Worship Times Engine for Rah-e-Deen-Islam
 * Default: Pakistan, Asia/Karachi (PKT - UTC+5)
 * Calculation Standard: University of Islamic Sciences, Karachi (Method 1)
 * Configurable Asr: Hanafi (School 1 - shadow 2x) / Shafi'i (School 0 - shadow 1x)
 * 12-Hour AM/PM format for all 10 timings:
 * 1. فجر (Fajr)
 * 2. طلوعِ آفتاب (Sunrise)
 * 3. اشراق (Ishraq - Sunrise + 15m)
 * 4. چاشت (Chasht / Duha - Mid-morning)
 * 5. ظہر (Zuhr / Dhuhr - Solar noon)
 * 6. عصر (Asr - Hanafi default)
 * 7. مغرب (Maghrib - Sunset)
 * 8. اوابین (Awwabin - After Maghrib Sunnah)
 * 9. عشاء (Isha - Karachi 18°)
 * 10. تہجد (Tahajjud - Last third of night)
 */

const PAK_CITIES = {
  vehari: { nameUrdu: 'وہاڑی', nameEn: 'Vehari', province: 'پنجاب', lat: 30.0452, lng: 72.3489 },
  lahore: { nameUrdu: 'لاہور', nameEn: 'Lahore', province: 'پنجاب', lat: 31.5497, lng: 74.3436 },
  islamabad: { nameUrdu: 'اسلام آباد', nameEn: 'Islamabad', province: 'وفاقی دارالحکومت', lat: 33.6844, lng: 73.0479 },
  karachi: { nameUrdu: 'کراچی', nameEn: 'Karachi', province: 'سندھ', lat: 24.8607, lng: 67.0011 },
  multan: { nameUrdu: 'ملتان', nameEn: 'Multan', province: 'پنجاب', lat: 30.1575, lng: 71.5249 },
  faisalabad: { nameUrdu: 'فیصل آباد', nameEn: 'Faisalabad', province: 'پنجاب', lat: 31.4504, lng: 73.1350 },
  rawalpindi: { nameUrdu: 'راولپنڈی', nameEn: 'Rawalpindi', province: 'پنجاب', lat: 33.5651, lng: 73.0169 },
  peshawar: { nameUrdu: 'پشاور', nameEn: 'Peshawar', province: 'خیبر پختونخوا', lat: 34.0151, lng: 71.5249 },
  quetta: { nameUrdu: 'کوئٹہ', nameEn: 'Quetta', province: 'بلوچستان', lat: 30.1798, lng: 66.9750 },
  sialkot: { nameUrdu: 'سیالکوٹ', nameEn: 'Sialkot', province: 'پنجاب', lat: 32.4945, lng: 74.5229 },
  gujranwala: { nameUrdu: 'گوجرانوالہ', nameEn: 'Gujranwala', province: 'پنجاب', lat: 32.1877, lng: 74.1945 },
  bahawalpur: { nameUrdu: 'بہاولپور', nameEn: 'Bahawalpur', province: 'پنجاب', lat: 29.3544, lng: 71.6911 },
  sargodha: { nameUrdu: 'سرگودھا', nameEn: 'Sargodha', province: 'پنجاب', lat: 32.0836, lng: 72.6711 },
  sahiwal: { nameUrdu: 'ساہیوال', nameEn: 'Sahiwal', province: 'پنجاب', lat: 30.6682, lng: 73.1114 },
  dera_ghazi_khan: { nameUrdu: 'ڈیرہ غازی خان', nameEn: 'Dera Ghazi Khan', province: 'پنجاب', lat: 30.0489, lng: 70.6455 },
  hyderabad: { nameUrdu: 'حیدرآباد', nameEn: 'Hyderabad', province: 'سندھ', lat: 25.3960, lng: 68.3578 },
  sukkur: { nameUrdu: 'سکھر', nameEn: 'Sukkur', province: 'سندھ', lat: 27.7052, lng: 68.8574 },
  abbottabad: { nameUrdu: 'ایبٹ آباد', nameEn: 'Abbottabad', province: 'خیبر پختونخوا', lat: 34.1688, lng: 73.2215 },
  muzaffarabad: { nameUrdu: 'مظفر آباد', nameEn: 'Muzaffarabad', province: 'آزاد کشمیر', lat: 34.3700, lng: 73.4708 },
  gilgit: { nameUrdu: 'گلگت', nameEn: 'Gilgit', province: 'گلگت بلتستان', lat: 35.9221, lng: 74.3087 }
};

class PrayerTimeService {
  constructor() {
    this.currentCityKey = 'vehari';
    this.currentSchool = 1; // 1 = Hanafi, 0 = Shafi'i/Standard
    this.currentTimings = null;
    this.lastFetchedDateStr = null;
    this.lastSuccessfulUpdate = null;
    this.listeners = [];
    this.autoRefreshInterval = null;
    this.timeZone = 'Asia/Karachi';
  }

  // Helper to convert 24h format "HH:MM" into clean 12-hour format "h:mm AM/PM"
  format12Hour(timeStr) {
    if (!timeStr || timeStr === '--:--') return '--:--';
    const parts = timeStr.split(':');
    let h = parseInt(parts[0], 10);
    const m = parts[1];
    if (isNaN(h)) return timeStr;
    const period = h >= 12 ? 'PM' : 'AM';
    h = h % 12 || 12;
    return `${h}:${m} ${period}`;
  }

  // Get current date & time specifically in Pakistan Time (Asia/Karachi)
  getPakistanDate() {
    const now = new Date();
    const formatter = new Intl.DateTimeFormat('en-GB', {
      timeZone: this.timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false
    });

    const parts = formatter.formatToParts(now);
    const getPart = (type) => parts.find(p => p.type === type)?.value || '';

    const day = getPart('day');
    const month = getPart('month');
    const year = getPart('year');
    const hour = getPart('hour');
    const minute = getPart('minute');
    const second = getPart('second');

    const dateStrDDMMYYYY = `${day}-${month}-${year}`;

    // Urdu formatted date string
    const monthsUrdu = ['جنوری', 'فروری', 'مارچ', 'اپریل', 'مئی', 'جون', 'جولائی', 'اگست', 'ستمبر', 'اکتوبر', 'نومبر', 'دسمبر'];
    const monthName = monthsUrdu[parseInt(month, 10) - 1];
    const dateFormattedUrdu = `${parseInt(day, 10)} ${monthName} ${year}ء`;

    // 12-hour formatted time with AM/PM
    const hourNum = parseInt(hour, 10);
    const ampm = hourNum >= 12 ? 'PM' : 'AM';
    const hour12 = hourNum % 12 || 12;
    const timeFormatted = `${hour12}:${minute}:${second} ${ampm} (PKT)`;

    return {
      day: parseInt(day, 10),
      month: parseInt(month, 10),
      year: parseInt(year, 10),
      hour: parseInt(hour, 10),
      minute: parseInt(minute, 10),
      second: parseInt(second, 10),
      totalSeconds: parseInt(hour, 10) * 3600 + parseInt(minute, 10) * 60 + parseInt(second, 10),
      dateStrDDMMYYYY,
      dateFormattedUrdu,
      timeFormatted
    };
  }

  // Fetch timings for selected Pakistani city and date
  async fetchTimings(cityKey = this.currentCityKey, school = this.currentSchool) {
    this.currentCityKey = cityKey;
    this.currentSchool = parseInt(school, 10);
    const city = PAK_CITIES[cityKey] || PAK_CITIES.vehari;
    const pktDate = this.getPakistanDate();
    this.lastFetchedDateStr = pktDate.dateStrDDMMYYYY;

    try {
      // Reliable AlAdhan API endpoint with Karachi method (1), city, and school parameter
      const url = `https://api.aladhan.com/v1/timingsByCity/${pktDate.dateStrDDMMYYYY}?city=${encodeURIComponent(city.nameEn)}&country=Pakistan&method=1&school=${this.currentSchool}`;
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 6000);

      const response = await fetch(url, { signal: controller.signal });
      clearTimeout(timeoutId);

      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const data = await response.json();

      if (data && data.data && data.data.timings) {
        const raw = data.data.timings;
        const hijri = data.data.date.hijri;
        this.lastSuccessfulUpdate = pktDate.timeFormatted;

        this.currentTimings = {
          cityKey,
          city,
          school: this.currentSchool,
          schoolLabel: this.currentSchool === 1 ? 'فقہ حنفی (سایہ دوگنا - مثلین)' : 'شافعی و جمہور (سایہ اکہرا - مثلِ اول)',
          methodName: 'جامعہ علوم اسلامیہ علامہ بنوری ٹاؤن، کراچی (AlAdhan API)',
          status: 'live_api',
          statusUrdu: 'آن لائن تصدیق شدہ لائیو اوقات (AlAdhan API)',
          timeZone: this.timeZone,
          dateGregorian: `${pktDate.dateFormattedUrdu} (${pktDate.dateStrDDMMYYYY})`,
          dateHijri: `${hijri.day} ${hijri.month.ar || hijri.month.en} ${hijri.year}ھ`,
          lastUpdated: pktDate.timeFormatted,
          lastSuccessfulUpdate: this.lastSuccessfulUpdate,
          timings: {
            Fajr: this.cleanTime(raw.Fajr),
            Sunrise: this.cleanTime(raw.Sunrise),
            Dhuhr: this.cleanTime(raw.Dhuhr),
            Asr: this.cleanTime(raw.Asr),
            Maghrib: this.cleanTime(raw.Maghrib),
            Isha: this.cleanTime(raw.Isha),
            Imsak: this.cleanTime(raw.Imsak),
            Midnight: this.cleanTime(raw.Midnight)
          }
        };

        this.calculateExtraTimes();
        this.notifyListeners();
        return this.currentTimings;
      }
      throw new Error('Invalid Data Structure');
    } catch (err) {
      console.warn(`[PrayerService] Live AlAdhan API unavailable (${err.message}). Using Karachi Method Astronomical Engine for ${city.nameUrdu}.`);
      return this.calculateOfflineTimings(city, this.currentSchool, pktDate, cityKey);
    }
  }

  cleanTime(timeStr) {
    return timeStr ? timeStr.split(' ')[0] : '--:--';
  }

  // Calculate all Nafl and Worship Timings:
  // - اشراق (Ishraq): Sunrise + 15 minutes (forbidden sunrise window ends)
  // - چاشت (Chasht / Duha): Mid-morning until Zawal
  // - اوابین (Awwabin): Maghrib + 12 minutes until Isha
  // - تہجد (Tahajjud): Last third of the night (Maghrib to Fajr)
  // - Converts all 10 timings into 12-hour AM/PM format
  calculateExtraTimes() {
    if (!this.currentTimings) return;
    const t = this.currentTimings.timings;

    const parseM = (timeStr) => {
      const [h, m] = timeStr.split(':').map(Number);
      return h * 60 + m;
    };
    const formatM = (totalM) => {
      const normalized = (Math.round(totalM) + 1440) % 1440;
      const h = Math.floor(normalized / 60);
      const min = normalized % 60;
      return `${String(h).padStart(2, '0')}:${String(min).padStart(2, '0')}`;
    };

    const sunriseM = parseM(t.Sunrise);
    const dhuhrM = parseM(t.Dhuhr);
    const maghribM = parseM(t.Maghrib);
    const fajrM = parseM(t.Fajr);

    // 1. اشراق (Ishraq):
    // Islamic method: 15 to 20 minutes after sunrise when the sun rises a spear's height (رمح)
    // and the prohibited sunrise window ends.
    const ishraqStartM = (sunriseM + 15) % 1440;
    const ishraqEndM = (sunriseM + 60) % 1440;

    // 2. چاشت (Chasht / صلاۃ الضحیٰ):
    // Islamic method: Starts after sun warms up (approx 45% between sunrise & Dhuhr) until Zawal
    const chashtStartM = (sunriseM + Math.round((dhuhrM - sunriseM) * 0.45)) % 1440;
    const zawalStartM = (dhuhrM - 12 + 1440) % 1440;

    // 3. اوابین (Awwabin):
    // Islamic method: Voluntary prayer performed immediately after Maghrib's Fard and Sunnah
    // (approx 10-15 minutes after Maghrib) until Isha.
    const awwabinStartM = (maghribM + 12) % 1440;

    // 4. تہجد (Tahajjud / صلاۃ اللیل):
    // Islamic method: Calculated from Maghrib to Fajr. Preferred time is the last 1/3 of the night.
    const nightMinutes = (fajrM + 1440 - maghribM) % 1440;
    const tahajjudStartM = (maghribM + Math.round(nightMinutes * 2 / 3)) % 1440;
    const midnightM = (maghribM + Math.round(nightMinutes / 2)) % 1440;

    // Store raw 24h
    t.Ishraq = formatM(ishraqStartM);
    t.Chasht = formatM(chashtStartM);
    t.Awwabin = formatM(awwabinStartM);
    t.Tahajjud = formatM(tahajjudStartM);

    // Store 12-hour formatted versions (e.g., عصر 4:01 PM، مغرب 5:38 PM)
    this.currentTimings.timings12 = {
      Fajr: this.format12Hour(t.Fajr),
      Sunrise: this.format12Hour(t.Sunrise),
      Ishraq: this.format12Hour(t.Ishraq),
      Chasht: this.format12Hour(t.Chasht),
      Dhuhr: this.format12Hour(t.Dhuhr),
      Asr: this.format12Hour(t.Asr),
      Maghrib: this.format12Hour(t.Maghrib),
      Awwabin: this.format12Hour(t.Awwabin),
      Isha: this.format12Hour(t.Isha),
      Tahajjud: this.format12Hour(t.Tahajjud)
    };

    // Metadata for worship intervals
    this.currentTimings.extra = {
      ishraqTime12: this.format12Hour(t.Ishraq),
      ishraqWindow: `${this.format12Hour(t.Ishraq)} تا ${this.format12Hour(formatM(ishraqEndM))}`,
      chashtTime12: this.format12Hour(t.Chasht),
      chashtWindow: `${this.format12Hour(t.Chasht)} تا ${this.format12Hour(formatM(zawalStartM))}`,
      awwabinTime12: this.format12Hour(t.Awwabin),
      awwabinWindow: `${this.format12Hour(t.Awwabin)} تا ${this.format12Hour(t.Isha)} (نمازِ عشاء)`,
      tahajjudTime12: this.format12Hour(t.Tahajjud),
      tahajjudWindow: `${this.format12Hour(t.Tahajjud)} تا ${this.format12Hour(t.Fajr)} (صبح صادق)`,
      zawalWindow: `${this.format12Hour(formatM(zawalStartM))} تا ${this.format12Hour(t.Dhuhr)}`,
      midnight12: this.format12Hour(formatM(midnightM))
    };
  }

  // Built-in Precision Solar Astronomical Engine for Pakistan
  // Based on Karachi University of Islamic Sciences specifications:
  // Fajr/Isha angle = 18 degrees, Sunrise/Sunset = 0.833 degrees, Standard Meridian = 75°E (PKT UTC+5)
  calculateOfflineTimings(city, school, pktDate = this.getPakistanDate(), cityKey = null) {
    const activeCityKey = cityKey || Object.keys(PAK_CITIES).find(k => PAK_CITIES[k].nameEn === city?.nameEn) || this.currentCityKey;
    const startOfYear = new Date(pktDate.year, 0, 0);
    const diff = new Date(pktDate.year, pktDate.month - 1, pktDate.day) - startOfYear;
    const dayOfYear = Math.floor(diff / (1000 * 60 * 60 * 24));

    const gamma = (2 * Math.PI / 365) * (dayOfYear - 1);

    const eot = 229.18 * (
      0.000075 +
      0.001868 * Math.cos(gamma) -
      0.032077 * Math.sin(gamma) -
      0.014615 * Math.cos(2 * gamma) -
      0.040849 * Math.sin(2 * gamma)
    );

    const declination = 0.006918 -
      0.399912 * Math.cos(gamma) +
      0.070257 * Math.sin(gamma) -
      0.006758 * Math.cos(2 * gamma) +
      0.000907 * Math.sin(2 * gamma) -
      0.002697 * Math.cos(3 * gamma) +
      0.00148 * Math.sin(3 * gamma);

    const latRad = (city.lat * Math.PI) / 180;
    const solarNoonMinutes = 12 * 60 + 4 * (75 - city.lng) - eot;

    const hourAngle = (angleDeg) => {
      const angleRad = (angleDeg * Math.PI) / 180;
      const cosH = (Math.sin(angleRad) - Math.sin(latRad) * Math.sin(declination)) /
                   (Math.cos(latRad) * Math.cos(declination));
      const clamped = Math.max(-1, Math.min(1, cosH));
      return (Math.acos(clamped) * 180 / Math.PI) / 15 * 60;
    };

    const fajrIshaH = hourAngle(-18);
    const sunriseSunsetH = hourAngle(-0.833);

    const asrShadowFactor = school === 1 ? 2 : 1;
    const zenithAngleRad = Math.abs(latRad - declination);
    const asrAltitudeAngleRad = Math.atan(1 / (asrShadowFactor + Math.tan(zenithAngleRad)));
    const cosAsrH = (Math.sin(asrAltitudeAngleRad) - Math.sin(latRad) * Math.sin(declination)) /
                    (Math.cos(latRad) * Math.cos(declination));
    const asrH = (Math.acos(Math.max(-1, Math.min(1, cosAsrH))) * 180 / Math.PI) / 15 * 60;

    const formatMinutes = (m) => {
      const totalM = Math.round(m);
      const h = Math.floor(totalM / 60) % 24;
      const min = totalM % 60;
      return `${String(h).padStart(2, '0')}:${String(min).padStart(2, '0')}`;
    };

    const fajrM = solarNoonMinutes - fajrIshaH;
    const sunriseM = solarNoonMinutes - sunriseSunsetH;
    const dhuhrM = solarNoonMinutes;
    const asrM = solarNoonMinutes + asrH;
    const maghribM = solarNoonMinutes + sunriseSunsetH;
    const ishaM = solarNoonMinutes + fajrIshaH;

    this.currentTimings = {
      cityKey: activeCityKey,
      city,
      school,
      schoolLabel: school === 1 ? 'فقہ حنفی (سایہ دوگنا - مثلین)' : 'شافعی و جمہور (سایہ اکہرا - مثلِ اول)',
      methodName: 'جامعہ علوم اسلامیہ علامہ بنوری ٹاؤن، کراچی (فلکیاتی شمسی حسابی نظام برائے پاکستان)',
      status: 'offline_fallback',
      statusUrdu: 'جامعہ علوم اسلامیہ علامہ بنوری ٹاؤن کراچی کے تسلیم شدہ اوقات (آف لائن بیک اپ موڈ)',
      timeZone: this.timeZone,
      dateGregorian: `${pktDate.dateFormattedUrdu} (${pktDate.dateStrDDMMYYYY})`,
      dateHijri: 'حسابی تقویمِ پاکستان',
      lastUpdated: `${pktDate.timeFormatted}`,
      lastSuccessfulUpdate: this.lastSuccessfulUpdate || 'آف لائن بیک اپ فعال',
      timings: {
        Fajr: formatMinutes(fajrM),
        Sunrise: formatMinutes(sunriseM),
        Dhuhr: formatMinutes(dhuhrM),
        Asr: formatMinutes(asrM),
        Maghrib: formatMinutes(maghribM),
        Isha: formatMinutes(ishaM)
      }
    };

    this.calculateExtraTimes();
    this.notifyListeners();
    return this.currentTimings;
  }

  // Calculate solar timings for any specific day in Pakistan
  calculateDaySolarTimings(city, school, day, month, year) {
    const startOfYear = new Date(year, 0, 0);
    const diff = new Date(year, month - 1, day) - startOfYear;
    const dayOfYear = Math.floor(diff / (1000 * 60 * 60 * 24));

    const gamma = (2 * Math.PI / 365) * (dayOfYear - 1);

    const eot = 229.18 * (
      0.000075 +
      0.001868 * Math.cos(gamma) -
      0.032077 * Math.sin(gamma) -
      0.014615 * Math.cos(2 * gamma) -
      0.040849 * Math.sin(2 * gamma)
    );

    const declination = 0.006918 -
      0.399912 * Math.cos(gamma) +
      0.070257 * Math.sin(gamma) -
      0.006758 * Math.cos(2 * gamma) +
      0.000907 * Math.sin(2 * gamma) -
      0.002697 * Math.cos(3 * gamma) +
      0.00148 * Math.sin(3 * gamma);

    const latRad = (city.lat * Math.PI) / 180;
    const solarNoonMinutes = 12 * 60 + 4 * (75 - city.lng) - eot;

    const hourAngle = (angleDeg) => {
      const angleRad = (angleDeg * Math.PI) / 180;
      const cosH = (Math.sin(angleRad) - Math.sin(latRad) * Math.sin(declination)) /
                   (Math.cos(latRad) * Math.cos(declination));
      const clamped = Math.max(-1, Math.min(1, cosH));
      return (Math.acos(clamped) * 180 / Math.PI) / 15 * 60;
    };

    const fajrIshaH = hourAngle(-18);
    const sunriseSunsetH = hourAngle(-0.833);

    const asrShadowFactor = school === 1 ? 2 : 1;
    const zenithAngleRad = Math.abs(latRad - declination);
    const asrAltitudeAngleRad = Math.atan(1 / (asrShadowFactor + Math.tan(zenithAngleRad)));
    const cosAsrH = (Math.sin(asrAltitudeAngleRad) - Math.sin(latRad) * Math.sin(declination)) /
                    (Math.cos(latRad) * Math.cos(declination));
    const asrH = (Math.acos(Math.max(-1, Math.min(1, cosAsrH))) * 180 / Math.PI) / 15 * 60;

    const formatMinutes = (m) => {
      const totalM = Math.round(m);
      const h = Math.floor(totalM / 60) % 24;
      const min = totalM % 60;
      return `${String(h).padStart(2, '0')}:${String(min).padStart(2, '0')}`;
    };

    return {
      day,
      month,
      year,
      Fajr: this.format12Hour(formatMinutes(solarNoonMinutes - fajrIshaH)),
      Sunrise: this.format12Hour(formatMinutes(solarNoonMinutes - sunriseSunsetH)),
      Dhuhr: this.format12Hour(formatMinutes(solarNoonMinutes)),
      Asr: this.format12Hour(formatMinutes(solarNoonMinutes + asrH)),
      Maghrib: this.format12Hour(formatMinutes(solarNoonMinutes + sunriseSunsetH)),
      Isha: this.format12Hour(formatMinutes(solarNoonMinutes + fajrIshaH))
    };
  }

  // Generate authentic calculated monthly timetable for any Pakistani city & month
  calculateMonthlyTimetable(cityKey = this.currentCityKey, school = this.currentSchool, year = null, month = null) {
    const city = PAK_CITIES[cityKey] || PAK_CITIES.vehari;
    const pktDate = this.getPakistanDate();
    const targetYear = year || pktDate.year;
    const targetMonth = month || pktDate.month;

    const daysInMonth = new Date(targetYear, targetMonth, 0).getDate();
    const rows = [];

    for (let d = 1; d <= daysInMonth; d++) {
      rows.push(this.calculateDaySolarTimings(city, school, d, targetMonth, targetYear));
    }

    return {
      city,
      school,
      year: targetYear,
      month: targetMonth,
      rows
    };
  }

  // Determine current active prayer, next upcoming prayer, and live countdown (hours, minutes, seconds)
  getNextPrayer(timings = this.currentTimings?.timings) {
    if (!timings) return null;

    const pktDate = this.getPakistanDate();
    const currentSec = (pktDate.hour * 3600) + (pktDate.minute * 60) + pktDate.second;

    const t12 = this.currentTimings?.timings12 || {};

    const prayers = [
      { key: 'Tahajjud', nameUrdu: 'تہجد', nameAr: 'صلاة التهجد', type: 'نفل', time: timings.Tahajjud, time12: t12.Tahajjud || this.format12Hour(timings.Tahajjud), icon: '🌌' },
      { key: 'Fajr', nameUrdu: 'فجر', nameAr: 'الفجر', type: 'فرض', time: timings.Fajr, time12: t12.Fajr || this.format12Hour(timings.Fajr), icon: '🌅' },
      { key: 'Sunrise', nameUrdu: 'طلوعِ آفتاب', nameAr: 'الشروق', type: 'طلوع', time: timings.Sunrise, time12: t12.Sunrise || this.format12Hour(timings.Sunrise), icon: '☀️', isSunrise: true },
      { key: 'Ishraq', nameUrdu: 'اشراق', nameAr: 'صلاة الإشراق', type: 'نفل', time: timings.Ishraq, time12: t12.Ishraq || this.format12Hour(timings.Ishraq), icon: '✨' },
      { key: 'Chasht', nameUrdu: 'چاشت', nameAr: 'صلاة الضحى', type: 'نفل', time: timings.Chasht, time12: t12.Chasht || this.format12Hour(timings.Chasht), icon: '☀️' },
      { key: 'Dhuhr', nameUrdu: 'ظہر', nameAr: 'الظهر', type: 'فرض', time: timings.Dhuhr, time12: t12.Dhuhr || this.format12Hour(timings.Dhuhr), icon: '🌤️' },
      { key: 'Asr', nameUrdu: 'عصر', nameAr: 'العصر', type: 'فرض', time: timings.Asr, time12: t12.Asr || this.format12Hour(timings.Asr), icon: '⛅' },
      { key: 'Maghrib', nameUrdu: 'مغرب', nameAr: 'المغرب', type: 'فرض', time: timings.Maghrib, time12: t12.Maghrib || this.format12Hour(timings.Maghrib), icon: '🌇' },
      { key: 'Awwabin', nameUrdu: 'اوابین', nameAr: 'صلاة الأوابين', type: 'نفل', time: timings.Awwabin, time12: t12.Awwabin || this.format12Hour(timings.Awwabin), icon: '🌿' },
      { key: 'Isha', nameUrdu: 'عشاء', nameAr: 'العشاء', type: 'فرض', time: timings.Isha, time12: t12.Isha || this.format12Hour(timings.Isha), icon: '🌙' }
    ].filter(p => p.time && p.time !== '--:--');

    let currentActive = prayers[prayers.length - 1]; // default Isha/night

    for (let i = 0; i < prayers.length; i++) {
      const [h, m] = prayers[i].time.split(':').map(Number);
      const prayerSec = (h * 3600) + (m * 60);

      if (currentSec >= prayerSec) {
        currentActive = prayers[i];
      }

      if (prayerSec > currentSec) {
        const diffSec = prayerSec - currentSec;
        const remainingHours = Math.floor(diffSec / 3600);
        const remainingMinutes = Math.floor((diffSec % 3600) / 60);
        const remainingSeconds = diffSec % 60;

        return {
          currentActive,
          next: prayers[i],
          remainingHours,
          remainingMinutes,
          remainingSeconds,
          totalRemainingSeconds: diffSec,
          remainingTotalMinutes: Math.floor(diffSec / 60),
          isTomorrow: false,
          countdownFormatted: `${String(remainingHours).padStart(2, '0')}:${String(remainingMinutes).padStart(2, '0')}:${String(remainingSeconds).padStart(2, '0')}`,
          countdownUrdu: `${remainingHours > 0 ? `${remainingHours} گھنٹے ` : ''}${remainingMinutes} منٹ ${remainingSeconds} سیکنڈ`
        };
      }
    }

    // After Isha at night, next prayer/worship is Tahajjud early morning tomorrow
    const firstPrayer = prayers[0];
    const [h, m] = firstPrayer.time.split(':').map(Number);
    const firstSec = (h * 3600) + (m * 60);
    const diffSec = (24 * 3600 - currentSec) + firstSec;
    const remainingHours = Math.floor(diffSec / 3600);
    const remainingMinutes = Math.floor((diffSec % 3600) / 60);
    const remainingSeconds = diffSec % 60;

    return {
      currentActive,
      next: firstPrayer,
      remainingHours,
      remainingMinutes,
      remainingSeconds,
      totalRemainingSeconds: diffSec,
      remainingTotalMinutes: Math.floor(diffSec / 60),
      isTomorrow: true,
      countdownFormatted: `${String(remainingHours).padStart(2, '0')}:${String(remainingMinutes).padStart(2, '0')}:${String(remainingSeconds).padStart(2, '0')}`,
      countdownUrdu: `${remainingHours > 0 ? `${remainingHours} گھنٹے ` : ''}${remainingMinutes} منٹ ${remainingSeconds} سیکنڈ`
    };
  }

  // Subscribe to updates
  addListener(callback) {
    if (typeof callback === 'function') {
      this.listeners.push(callback);
    }
  }

  notifyListeners() {
    for (const cb of this.listeners) {
      try { cb(this.currentTimings); } catch (e) { console.error(e); }
    }
  }

  // Automatic refresh daemon: checks Pakistan date rollover every 5 seconds
  startAutoRefreshDaemon() {
    if (this.autoRefreshInterval) clearInterval(this.autoRefreshInterval);

    this.autoRefreshInterval = setInterval(() => {
      const pkt = this.getPakistanDate();
      if (this.lastFetchedDateStr && pkt.dateStrDDMMYYYY !== this.lastFetchedDateStr) {
        console.log(`[PrayerService] Midnight date rollover detected in Asia/Karachi (${pkt.dateStrDDMMYYYY}). Automatically refreshing timings...`);
        this.fetchTimings(this.currentCityKey, this.currentSchool);
      }
    }, 5000);
  }
}

// Global service instance
window.PAK_CITIES = PAK_CITIES;
window.prayerService = new PrayerTimeService();
window.prayerService.startAutoRefreshDaemon();

