const HADITH_DATABASE = [
  // PART 1 (1 - 100)
  {
    id: 1,
    part: 1,
    category: 'عقیدہ و ایمان',
    categoryEn: 'faith',
    collection: 'صحیح البخاری',
    collectionEn: 'Sahih al-Bukhari',
    hadithNumber: 1,
    book: 'کتاب بدء الوحی',
